sys_script_include.script:
var GetManagerSI = Class.create();
GetManagerSI.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getManager: function() {

        var user = this.getParameter('sysparm_sys_id');
		gs.log("hi_1");
        var gr = new GlideRecord('sys_user');
		gs.log("hi_2 " + gr.get(user));
        if (gr.get(user)) {

            var Userdata = new GlideRecord('sys_user');
gs.log("hi_3 " +Userdata.get(user));
            if (Userdata.get(user)) {

                var json = new JSON();

                var results = {
					"manager": Userdata.getValue("manager"),
                };
				gs.log('hi_04 '+ Userdata.getValue("manager"));
                return json.encode(results);

            }

        } else {

            return null;

        }

    },
    type: 'GetManagerSI'
});
